mapper.select:
SELECT COUNT(*) FROM MEMBER_TB
AND MB_GRADE = #{s_grade}
AND (MB_NAME LIKE '%' || #{s_keyword} || '%' OR MB_EMAIL LIKE '%' || #{s_keyword} || '%')

	SELECT *
	  FROM 
	  	(SELECT A.* , 
	  			rownum AS rn
	  	   FROM (
	  	   		 SELECT * FROM MEMBER_TB



  					AND MB_GRADE = #{s_grade}




  					AND (MB_NAME LIKE '%' || #{s_keyword} || '%'
  					 OR MB_EMAIL LIKE '%' || #{s_keyword} || '%')


				 ORDER BY MB_ID DESC
				) A
		)
	 WHERE rn BETWEEN #{start} AND #{end}
